code_sketch:
trait Component { fn update(&mut self, transform: &mut Transform, dt: f32); }

struct Entity {
    transform: Transform,                 // pan-domain state
    parts: Vec<Box<dyn Component>>,       // pluggable slots
}

impl Entity {
    fn update(&mut self, dt: f32) {
        let Entity { transform, parts } = self;   // split the borrows
        for p in parts.iter_mut() { p.update(transform, dt) }
    }
}

